/** Project-owned review notes. Times are seconds in the reviewed Run. */
export type FeedbackComment = {
    readonly id: string;
    readonly run: string;
    readonly at: number;
    readonly text: string;
    readonly resolved?: boolean;
};
export type FeedbackDocument = {
    readonly comments: readonly FeedbackComment[];
};
export type FeedbackView = FeedbackDocument & {
    readonly file: string;
    readonly run: string;
};
export type FeedbackMutation = {
    readonly type: "add";
    readonly comment: FeedbackComment;
} | {
    readonly type: "replace";
    readonly before: FeedbackComment;
    readonly comment: FeedbackComment;
} | {
    readonly type: "delete";
    readonly before: FeedbackComment;
};
export declare function readFeedbackComment(value: unknown): FeedbackComment;
export declare function readFeedbackDocument(value: unknown): FeedbackDocument;
export declare function readFeedbackMutation(value: unknown): FeedbackMutation;
export declare function feedbackClock(seconds: number): string;
